//! Tests for the committed Round 11 example goldens.
//!
//! The golden marks readings of the standing example meet and
//! of the constructed meet are regenerated by the marks command
//! itself, and these pins fail if an example, a golden, or the
//! reading drifts away from the hand computed marks of either
//! meet, and the reconciliation pins read the reign, days, and
//! report readings over the same files and fail when the marks
//! reading disagrees with them over the spells and the counts.

use std::fs;
use std::path::PathBuf;

use paceghost::cli::dispatch;
use paceghost::meet::{load_meet_file, meet_days, meet_marks, meet_reign, meet_report};
use paceghost::pytext::PText;

fn reader(bytes: &[u8]) -> Option<String> {
    let path = String::from_utf8_lossy(bytes).into_owned();
    let data = std::fs::read(path).ok()?;
    String::from_utf8(data).ok()
}

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

fn golden_lines(name: &str) -> Vec<String> {
    let golden = fs::read_to_string(examples_dir().join(name)).expect("the golden file reads");
    assert!(golden.ends_with('\n'));
    golden.lines().map(str::to_string).collect()
}

fn command_lines(command: &str, file: &str) -> Vec<String> {
    let argv: Vec<PText> = vec![
        PText::from_text(command),
        PText::from_text(examples_dir().join(file).to_str().unwrap()),
    ];
    let outcome = dispatch(&argv, &reader);
    assert_eq!(outcome.code, 0);
    outcome.stdout
}

#[test]
fn test_the_example_marks_match_the_golden_bytes() {
    let (meet, defects) = load_meet_file(&examples_dir().join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_marks(&meet).expect("the example marks read");
    assert_eq!(lines, golden_lines("meet-marks-golden.txt"));
}

#[test]
fn test_the_marks_command_prints_the_golden_marks() {
    assert_eq!(
        command_lines("marks", "meet.json"),
        golden_lines("meet-marks-golden.txt")
    );
}

#[test]
fn test_the_constructed_marks_match_the_golden_bytes() {
    let (meet, defects) = load_meet_file(&examples_dir().join("constructed-meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the constructed meet loads");
    let lines = meet_marks(&meet).expect("the constructed marks read");
    assert_eq!(lines, golden_lines("constructed-meet-marks-golden.txt"));
}

#[test]
fn test_the_marks_command_prints_the_constructed_golden_marks() {
    assert_eq!(
        command_lines("marks", "constructed-meet.json"),
        golden_lines("constructed-meet-marks-golden.txt")
    );
}

#[test]
fn test_the_example_closings_reconcile_with_the_standing_readings() {
    let (meet, defects) = load_meet_file(&examples_dir().join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let marks = meet_marks(&meet).expect("the example marks read");
    let set_or_took = marks
        .iter()
        .filter(|line| {
            line.contains(", set the standing record") || line.contains(", took the record from")
        })
        .count();
    let reign = meet_reign(&meet).expect("the reign reads");
    let spells: usize = reign
        .last()
        .expect("the reign closes")
        .split(", spells ")
        .nth(1)
        .and_then(|rest| rest.split(',').next())
        .and_then(|text| text.parse().ok())
        .expect("the reign closing names its spells");
    assert_eq!(set_or_took, spells);
    let days = meet_days(&meet).expect("the days read");
    let per_day: usize = days
        .iter()
        .filter(|line| line.starts_with("day, the "))
        .map(|line| {
            line.split(", marks ")
                .nth(1)
                .and_then(|rest| rest.split(',').next())
                .and_then(|text| text.parse::<usize>().ok())
                .expect("a day line names its marks")
        })
        .sum();
    let closing = marks.last().expect("the marks close");
    assert!(
        closing.contains(&format!("marks walked {}", per_day)),
        "{}",
        closing
    );
    let report = meet_report(&meet).expect("the report reads");
    assert_eq!(report.last().map(String::as_str), Some("days read, 3"));
    assert!(closing.ends_with("days 3"), "{}", closing);
}

#[test]
fn test_the_constructed_second_day_stands_all_below() {
    let lines = golden_lines("constructed-meet-marks-golden.txt");
    let section: Vec<&String> = lines
        .iter()
        .skip_while(|line| !line.starts_with("day, the second day"))
        .take_while(|line| !line.starts_with("day, the third day"))
        .collect();
    assert_eq!(section.len(), 3);
    assert!(section[1].contains(", stood below the standing record of 400"));
    assert!(section[2].contains(", stood below the standing record of 500"));
    assert!(lines
        .iter()
        .any(|line| line.contains(", extended its own record")));
}
